        [Fact]
        public void Test_HiddenContentAriaHiddenStillRendered()
        {
            // aria-hidden only hides content from assistive tech, not visually — it must still be rendered
            var result = HtmlToMarkdownConverter.Convert("<p>visible</p><div aria-hidden=\"true\">still shown</div><p>also visible</p>", new ConversionOptions());
            Assert.Contains("visible", result.Content.ToString());
            Assert.Contains("still shown", result.Content.ToString());
            Assert.Contains("also visible", result.Content.ToString());

        }

        [Fact]
        public void Test_HiddenContentDisplayNoneDropped()
        {
            // Elements hidden via inline style="display:none" must not appear in the output
            var result = HtmlToMarkdownConverter.Convert("<p>visible</p><div style=\"display:none\">secret hidden text</div><p>also visible</p>", new ConversionOptions());
            Assert.DoesNotContain("secret hidden text", result.Content.ToString());
            Assert.Contains("visible", result.Content.ToString());
            Assert.Contains("also visible", result.Content.ToString());

        }

